package dev.zomboid.tacz;import net.minecraft.client.Minecraft;public class Checks {static int n;static void check(boolean v){n++;if(!v)throw new AssertionError(n);}public static class Event {public String name="crosshair";public boolean canceled;public String getName(){return name;}public Object getGuiGraphics(){return new Object();}public void setCanceled(boolean value){canceled=value;}}public static class Graphics {public int fills;public void fill(int a,int b,int c,int d,int e){fills++;}}public static void main(String[] args){Minecraft mc=Minecraft.M;check(Bridge.thirdPerson());mc.options.view.first=true;check(!Bridge.thirdPerson());Event event=new Event();mc.player.ads=true;check(!Bridge.drawEvent(event)&&!event.canceled);mc.options.view.first=false;check(Bridge.drawEvent(event)&&event.canceled);check(com.tacz.guns.client.event.RenderCrosshairEvent.markers==1);event=new Event();mc.player.ads=false;check(!Bridge.drawEvent(event));event.name="hotbar";mc.player.ads=true;check(!Bridge.drawEvent(event));Graphics graphics=new Graphics();Bridge.draw(graphics,100,100);check(graphics.fills==25);graphics=new Graphics();Bridge.line(graphics,new double[]{0,0},new double[]{300,300});check(graphics.fills>0&&graphics.fills<48);mc.player.gun=false;check(!Bridge.thirdPerson());mc.player=null;check(!Bridge.thirdPerson());check(Weather.cycle(0)==0);check(Weather.cycle(24000)==0);check(Weather.cycle(24600)==1);check(Weather.cycle(29999)<.01);check(Weather.cycle(30000)==0);check(Weather.cycle(96600)==1);System.out.println("Passed "+n+" third-person HUD checks (API doubles)");}}
